package io.knowledgebrain.knowledge;
import java.util.*;import java.time.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import org.springframework.mock.web.MockHttpServletRequest;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_KNOWLEDGE_DATABASE_URL",matches=".+")
class ActivityExportIntegrationTest {
 PGSimpleDataSource db;JdbcTemplate jdbc;ClaimStore claims;ConceptStore concepts;String schema;UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor,subject,predicate,target;String trace="a".repeat(32);
 @BeforeEach void setup(){db=new PGSimpleDataSource();db.setURL(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_URL"));db.setUser("brain_knowledge");db.setPassword(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_PASSWORD"));schema="claim_activity_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(db).execute("CREATE SCHEMA "+schema);db.setCurrentSchema(schema);Flyway.configure().dataSource(db).locations("classpath:db/migration").load().migrate();jdbc=new JdbcTemplate(db);claims=new ClaimStore(db,Clock.systemUTC());concepts=new ConceptStore(db,Clock.systemUTC());space=ids.next();actor=ids.next();subject=concepts.create(space,actor,"Subject","",trace).conceptId();predicate=concepts.create(space,actor,"Predicate","",trace).conceptId();target=concepts.create(space,actor,"Target","",trace).conceptId();}
 @AfterEach void clean(){jdbc.execute("DROP SCHEMA "+schema+" CASCADE");}
 MockHttpServletRequest request(){var r=new MockHttpServletRequest("GET","/internal/knowledge/activity-events");r.setSecure(true);r.addHeader("Authorization","Bearer "+"a".repeat(43));return r;}
 ActivityExportController api(){return new ActivityExportController(db,"a".repeat(43),new SimpleMeterRegistry());}
 @Test void originalMixedVersionHistorySurvivesRetirementAndWatermarkExcludesLaterEvents()throws Exception{var c=claims.create(space,subject,actor,predicate,new ClaimStore.ObjectValue("CONCEPT",target),trace);var stored=jdbc.queryForMap("SELECT id,payload FROM outbox_event WHERE aggregateid=?",c.claimId());var e=io.knowledgebrain.contracts.knowledge.claim.v2.EventEnvelopeV2.parseFrom((byte[])stored.get("payload"));var legacy=e.toBuilder().setEventVersion(1).build().toByteArray();jdbc.update("UPDATE outbox_event SET aggregatetype='claim',schema_artifact='claim-events',payload=? WHERE id=?",legacy,stored.get("id"));for(int v=1;v<6;v++)claims.change(space,subject,c.claimId(),actor,v,predicate,new ClaimStore.ObjectValue("NUMBER",null,Integer.toString(v)),false,trace);claims.change(space,subject,c.claimId(),actor,6,null,null,true,trace);concepts.change(space,subject,actor,1,null,null,true,trace);var api=api();var first=api.page(null,null,request());assertEquals("no-store",first.getHeaders().getCacheControl());assertEquals(5,first.getBody().items().size());assertNotNull(first.getBody().nextAfter());var mark=first.getBody().through();var rows=new ArrayList<ActivityExportController.Item>();UUID after=null;do{var page=api.page(after,mark,request()).getBody();assertEquals(mark,page.through());rows.addAll(page.items());after=page.nextAfter();}while(after!=null);assertEquals(7,rows.size());assertEquals("knowledge.claim.v1",rows.getFirst().topic());assertTrue(rows.subList(1,7).stream().allMatch(i->i.topic().equals("knowledge.claim.v2")));for(var row:rows)assertArrayEquals(jdbc.queryForObject("SELECT payload FROM outbox_event WHERE id=?",byte[].class,row.eventId()),Base64.getDecoder().decode(row.payload()));assertEquals(7,claims.history(space,subject,c.claimId(),Long.MAX_VALUE,10).size());var another=concepts.create(space,actor,"Another","",trace);claims.create(space,another.conceptId(),actor,predicate,new ClaimStore.ObjectValue("BOOLEAN",null,"false"),trace);assertTrue(api.page(mark,mark,request()).getBody().items().isEmpty());assertEquals(1,api.page(mark,null,request()).getBody().items().size());}
 @Test void serviceCredentialHttpsAndStrictReadRequestAreRequired(){var api=api();for(String condition:List.of("http","cookie","wrong","duplicate")){var r=request();switch(condition){case "http"->r.setSecure(false);case "cookie"->r.addHeader("Cookie","__Host-brain_guest=x");case "wrong"->{r.removeHeader("Authorization");r.addHeader("Authorization","Bearer "+"b".repeat(43));}case "duplicate"->r.addHeader("Authorization","Bearer "+"a".repeat(43));}assertEquals(401,assertThrows(ResponseStatusException.class,()->api.page(null,null,r)).getStatusCode().value());}for(String condition:List.of("unknown","duplicate","body","transfer")){var r=request();switch(condition){case "unknown"->r.addParameter("kind","CLAIM");case "duplicate"->r.addParameter("after","a","b");case "body"->r.setContent("{}".getBytes());case "transfer"->r.addHeader("Transfer-Encoding","chunked");}assertEquals(400,assertThrows(ResponseStatusException.class,()->api.page(null,null,r)).getStatusCode().value());}assertEquals(400,assertThrows(ResponseStatusException.class,()->api.page(UUID.randomUUID(),null,request())).getStatusCode().value());}
}
